/**
 * name: Tarkista suomi (Voikko)
 * category: Teksti
 * description: Valittujen tekstikehysten paikallinen suomen oikoluku.
 * version: 1.6.0
 * compatibility: Affinity 3.3
 */
"use strict";

// Pure helpers also run under Node for regression tests. The installed file is
// generated by setup.py; it contains this computer's local service key.
const VoikkoCore = (() => {
    const wordPattern = /[\p{L}\p{M}]+(?:[-'’][\p{L}\p{M}]+)*/gu;
    function snapshot(story, begin, end) {
        let text = "";
        const starts = [], ends = [];
        for (let pos = begin; pos < end; pos++) {
            const glyph = story.getGlyph(pos);
            // Fields, tables, paragraph breaks and embedded objects cannot turn
            // into spelling candidates or shift subsequent glyph offsets.
            const value = glyph.isCharGlyph ? glyph.string : (glyph.isHardBreakGlyph ? "\n" : " ");
            for (let i = 0; i < value.length; i++) {
                text += value[i]; starts.push(pos); ends.push(pos + 1);
            }
        }
        return {text, starts, ends, begin, end};
    }
    function words(snap) {
        const result = [];
        wordPattern.lastIndex = 0;
        let match;
        while ((match = wordPattern.exec(snap.text))) {
            if (Array.from(match[0]).length > 100) continue;
            result.push({word: match[0], begin: snap.starts[match.index],
                end: snap.ends[match.index + match[0].length - 1]});
        }
        return result;
    }
    function batches(words) {
        const result = []; let batch = [], size = 0;
        for (const word of new Set(words)) {
            const next = encodeURIComponent(JSON.stringify(word)).length + 3;
            if (batch.length && (batch.length >= 40 || size + next > 6000)) {
                result.push(batch); batch = []; size = 0;
            }
            batch.push(word); size += next;
        }
        if (batch.length) result.push(batch);
        return result;
    }
    function replacementAllowed(value) {
        return typeof value === "string" && /^[\p{L}\p{M}]+(?:[-'’][\p{L}\p{M}]+)*$/u.test(value)
            && Array.from(value).length <= 100;
    }
    return {snapshot, words, batches, replacementAllowed};
})();

function runAffinityVoikko() {
    const {app} = require("/application.js");
    const {Document} = require("/document.js");
    const {Selection, TextSelection} = require("/selections.js");
    const {StoryRange} = require("affinity:story");
    const {DocumentCommand, CompoundCommandBuilder} = require("/commands.js");
    const {StoryDelta} = require("/storydelta.js");
    const {FillDescriptor} = require("/fills.js");
    const {SVG11} = require("/colours.js");
    const {BlendMode} = require("affinity:common");
    const {Dialog, DialogResult, HorizontalAlignment} = require("/dialog.js");
    const {HttpRequest, RequestMethod} = require("/network.js");
    const KEY = "__VOIKKO_KEY__";
    const BASE = "http://127.0.0.1:17655";
    if (KEY.indexOf("__") === 0)
        throw new Error("Käynnistä ensin Affinity-oikoluku.exe tai Kaynnista-Affinity-oikoluku.cmd ja lisää syntynyt Tarkista-suomi.js Affinityyn.");
    const doc = Document.current;
    if (!doc) throw new Error("Avaa asiakirja ja valitse tarkistettavat tekstikehykset.");

    function request(path, method = RequestMethod.Get) {
        const req = HttpRequest.create(BASE + path, method);
        req.setHeaderValue("X-Voikko-Key", KEY);
        req.setTimeoutInSec(5);
        function decode(result) {
            if (!result || !result.response || !result.response.isSuccess)
                throw new Error("Affinity-oikolukuun ei saada yhteyttä. Käynnistä Affinity-oikoluku.exe tai Kaynnista-Affinity-oikoluku.cmd. " +
                    "Skriptin verkkoyhteyden on oltava sallittu Affinityssä.");
            const content = result.response.content;
            const text = typeof content === "string" ? content :
                new TextDecoder().decode(content.buffer ? content : new Uint8Array(content));
            return JSON.parse(text);
        }
        return decode(req.do());
    }
    function rangeSelection(node, begin, end) {
        const sel = Selection.create(doc, node);
        sel.addSubSelectionForNode(node, TextSelection.create(new StoryRange(begin, end)));
        return sel;
    }

    const originalSelection = doc.selection;
    const originalSpread = doc.currentSpread;
    const frames = [], seen = new Set();
    let total = 0, skipped = 0, visited = 0;
    function collect(node) {
        if (++visited > 5000) throw new Error("Valitse pienempi tasoryhmä (enintään 5 000 tasoa).");
        // Applied masters are exposed as a PhysicalNode containing their
        // page-instance frames, rather than as a selected text node.
        if (!node.isTextNode) {
            if (node.isEmbeddedDocumentNode || node.isLocalEditable === false) { skipped++; return; }
            if (node.children && node.children.length) {
                for (const child of node.children) collect(child);
            } else { skipped++; }
            return;
        }
        if (!node.isEditable) { skipped++; return; }
        const flow = node.isFrameTextNode ? Array.from(node.textFrameInterface.textFlowNodes) : [node];
        if (!flow.length) flow.push(node);
        if (frames.some(f => f.flow.some(n => n.isSameNode(node)))) return;
        const story = node.storyInterface.story;
        if (story.isTable) { skipped++; return; }
        total += story.length;
        if (total > 50000) throw new Error("Valitse pienempi tekstimäärä (enintään 50 000 merkkiä kerralla).");
        const snap = VoikkoCore.snapshot(story, 0, story.length);
        frames.push({node, flow, story, snap, length: story.length});
    }
    const selectionRoots = Array.from(originalSelection.nodes);
    // In Affinity 3.3, clicking an applied master in Layers can produce an
    // empty SDK selection. Its page-instance children remain accessible on
    // the current spread. Never traverse back to the master source spread.
    const useCurrentSpread = !selectionRoots.length;
    const roots = useCurrentSpread ? Array.from(originalSpread.children) : selectionRoots;
    for (const node of roots) collect(node);
    if (!frames.length) throw new Error("Valitse tekstikehys tai sitä sisältävä ryhmä/master-taso. " +
        "Valinnasta ei löytynyt muokattavaa tekstiä. Lukittuja tekstejä ja taulukoita ei tarkisteta.");
    const occurrences = [];
    for (const frame of frames) {
        for (const token of VoikkoCore.words(frame.snap)) {
            token.frame = frame;
            token.owner = frame.flow.find(n => {
                const range = n.storyInterface.storyRange;
                return range && token.begin >= range.begin && token.begin < range.end;
            }) || frame.flow[frame.flow.length - 1];
            token.flowIndex = frame.flow.findIndex(n => n.isSameNode(token.owner));
            occurrences.push(token); seen.add(token.word);
        }
    }
    const chunks = VoikkoCore.batches(seen), incorrect = new Set();
    function fail(error) { app.alert(String(error.message || error), "Suomen oikoluku"); }
    function checkBatches() {
        // Affinity's MCP execution can finish before doAsync callbacks run.
        // Bounded local requests work in both MCP and the Scripts Library.
        const deadline = Date.now() + 10000;
        for (const batch of chunks) {
            if (Date.now() > deadline)
                throw new Error("Tarkistus kesti liian kauan. Valitse pienempi tekstimäärä.");
            const data = request("/check?words=" + encodeURIComponent(JSON.stringify(batch)));
            if (!Array.isArray(data.results) || data.results.length !== batch.length) {
                fail(new Error("Voikko palautti virheellisen vastauksen.")); return;
            }
            for (let i = 0; i < batch.length; i++) {
                const item = data.results[i];
                if (item.word !== batch[i] || typeof item.correct !== "boolean") {
                    fail(new Error("Voikko-vastauksen sanat eivät täsmää.")); return;
                }
                if (!item.correct) incorrect.add(item.word);
            }
        }
        review(occurrences.filter(o => incorrect.has(o.word)));
    }

    function review(issues) {
        if (!Document.current || !doc.isSameObject(Document.current))
            throw new Error("Aktiivinen asiakirja vaihtui. Käynnistä tarkistus uudelleen.");
        if (!issues.length) {
            app.alert("Voikko ei löytänyt kirjoitusvirheitä. Tarkistettu " + seen.size +
                " eri sanaa." + (skipped ? " Ohitettuja tasoja: " + skipped : ""), "Suomen oikoluku");
            return;
        }
        const dialog = Dialog.create("Suomen oikoluku – Voikko");
        dialog.initialWidth = 380;
        const column = dialog.addColumn();
        const header = column.addGroup("");
        if (useCurrentSpread) {
            const scope = header.addStaticText("", "Nykyinen aukeama ja sen tekstiketjut");
            scope.isFullWidth = true;
        }
        const progress = header.addStaticText("", "");
        progress.isFullWidth = true;
        const current = column.addGroup("Tarkistettava sana").addStaticText("", "");
        current.isFullWidth = true;
        const group = column.addGroup("Ehdotukset");
        const suggestionList = group.addStaticText("", "");
        suggestionList.isFullWidth = true;
        // Native button labels cannot be changed after creation. Keep eight
        // reusable rows with changing text and a neighbouring selection button.
        const suggestionRows = Array.from({length: 8}, () => {
            const row = group.addColumnStack();
            const textColumn = row.addColumn();
            textColumn.widthProportion = 1;
            const text = textColumn.addGroup("").addStaticText("", "");
            text.isFullWidth = true;
            text.textHorizontalAlignment = HorizontalAlignment.Left;
            const button = row.addColumn().addGroup("").addButton("Valitse");
            button.alignment = HorizontalAlignment.Left;
            row.isVisible = false;
            return {row, text, button};
        });
        const actions = column.addGroup("Korvaava sana");
        const replacement = actions.addTextBox("", "");
        replacement.isFullWidth = true;
        const replace = actions.addButton("Korvaa ja seuraava");
        replace.isFullWidth = true;
        const skip = actions.addButton("Ohita tämä");
        skip.isFullWidth = true;
        const skipAll = actions.addButton("Ohita sana tässä tarkistuksessa");
        skipAll.isFullWidth = true;
        const addWord = actions.addButton("Lisää sanastoon");
        addWord.isFullWidth = true;
        const hint = actions.addStaticText("", "OK hyväksyy korjaukset · Cancel peruu");
        hint.isFullWidth = true;
        const pending = [], ignored = new Set(), addedWords = new Set();
        let hasPreview = false;
        let lastNavigatedSpread = null;
        const highlight = StoryDelta.createHighlightFill(FillDescriptor.createSolid(SVG11.yellow, BlendMode.Normal));
        function clearHighlight() {
            if (hasPreview) { doc.clearPreviews(); hasPreview = false; }
        }
        let index = 0, values = [];
        suggestionRows.forEach(({button}, i) => {
            button.onClickHandler = () => {
                if (values[i]) replacement.text = values[i];
            };
        });
        function show() {
            clearHighlight();
            while (index < issues.length && (ignored.has(issues[index].word) ||
                addedWords.has(issues[index].word.normalize("NFC").toLocaleLowerCase("fi")))) index++;
            values = [];
            suggestionRows.forEach(({row, button}) => { row.isVisible = false; button.isEnabled = false; });
            if (index === issues.length) {
                progress.text = "Valmis · " + pending.length + " korjausta odottaa OK:ta";
                current.text = ""; replacement.text = ""; suggestionList.text = "";
                suggestionList.isVisible = false;
                replace.isEnabled = false; skip.isEnabled = false; skipAll.isEnabled = false;
                addWord.isEnabled = false;
                replacement.isEnabled = false;
            } else {
                const issue = issues[index];
                progress.text = (index + 1) + " / " + issues.length + " — hyväksytty " + pending.length;
                current.text = issue.word;
                replacement.text = issue.word;
                replace.isEnabled = false;
                addWord.isEnabled = true;
                suggestionList.text = "Haetaan ehdotuksia…";
                suggestionList.isVisible = true;
                const data = request("/suggest?word=" + encodeURIComponent(issue.word));
                values = (data.suggestions || []).filter(VoikkoCore.replacementAllowed).slice(0, suggestionRows.length);
                suggestionList.text = values.length ? "" :
                    "Ei ehdotuksia – kirjoita korjaus itse.";
                suggestionList.isVisible = values.length === 0;
                values.forEach((value, i) => {
                    const {row, text, button} = suggestionRows[i];
                    text.text = value; button.isEnabled = true; row.isVisible = true;
                });
                replacement.text = values[0] || issue.word;
                replace.isEnabled = true;
                // Native preview is temporary: it is cleared before any real
                // correction and on every exit, including Cancel and errors.
                const preview = CompoundCommandBuilder.create();
                const spread = issue.owner.spread;
                // Preview changes the logical spread but does not scroll the
                // viewport. Navigate separately, including the first issue
                // when the user has panned away from the active spread.
                if (spread && (!lastNavigatedSpread || !spread.isSameNode(lastNavigatedSpread))) {
                    doc.executeCommand(DocumentCommand.createSetCurrentSpread(spread));
                    lastNavigatedSpread = spread;
                }
                const selection = rangeSelection(issue.owner, issue.begin, issue.end);
                preview.addCommand(DocumentCommand.createSetSelection(selection));
                preview.addCommand(DocumentCommand.createFormatText(selection, highlight));
                hasPreview = true;
                doc.executeCommand(preview.createCommand(), true);
            }
        }
        function safely(action) { return () => { try { action(); } catch (e) { fail(e); } }; }
        replace.onClickHandler = safely(() => {
            const issue = issues[index], value = replacement.text.trim();
            if (!VoikkoCore.replacementAllowed(value)) {
                app.alert("Kirjoita yksi sana. Säilytä kappale- ja sanavälit ennallaan.", "Suomen oikoluku"); return;
            }
            if (value !== issue.word) pending.push({...issue, replacement: value});
            index++; show();
        });
        skip.onClickHandler = safely(() => { index++; show(); });
        skipAll.onClickHandler = safely(() => { ignored.add(issues[index].word); index++; show(); });
        addWord.onClickHandler = safely(() => {
            const word = issues[index].word;
            const result = request("/add?word=" + encodeURIComponent(word), RequestMethod.Post);
            if (!result.added) throw new Error("Sanaa ei voitu lisätä sanastoon.");
            addedWords.add(word.normalize("NFC").toLocaleLowerCase("fi"));
            index++; show();
        });
        try {
            show();
            const result = dialog.runModal();
            clearHighlight();
            if (result != DialogResult.Ok || !pending.length) return;
            // Validate every story BEFORE making any edits. Network callbacks or
            // user edits must never cause corrections at stale glyph positions.
            for (const frame of frames) {
                if (!frame.node.isEditable) throw new Error("Tekstitaso lukittiin. Korjauksia ei tehty.");
                const live = frame.node.storyInterface.story;
                if (live.length !== frame.length ||
                    VoikkoCore.snapshot(live, 0, live.length).text !== frame.snap.text)
                    throw new Error("Teksti muuttui tarkistuksen aikana. Korjauksia ei tehty; tarkista uudelleen.");
            }
            const commands = CompoundCommandBuilder.create();
            let commandSpread = doc.currentSpread;
            for (const frame of frames) {
                const fixes = pending.filter(p => p.frame === frame).sort((a, b) => b.begin - a.begin);
                for (const fix of fixes) {
                    if (!fix.owner.isEditable) throw new Error("Korjattava tekstikehys on lukittu. Muutoksia ei tehty.");
                    if (frame.story.getGlyphAttsRunEnd(fix.begin, fix.end) < fix.end)
                        throw new Error("Sanan ”" + fix.word + "” sisällä on eri muotoiluja. " +
                            "Korjaa se käsin ja tarkista uudelleen. Muutoksia ei tehty.");
                    const style = StoryDelta.createFromGlyphAtts(frame.story.getGlyphAtts(fix.begin));
                    const spread = fix.owner.spread;
                    if (spread && !spread.isSameNode(commandSpread)) {
                        commands.addCommand(DocumentCommand.createSetCurrentSpread(spread));
                        commandSpread = spread;
                    }
                    commands.addCommand(DocumentCommand.createSetText(
                        rangeSelection(fix.owner, fix.begin, fix.end), fix.replacement));
                    commands.addCommand(DocumentCommand.createFormatText(rangeSelection(fix.owner,
                        fix.begin, fix.begin + Array.from(fix.replacement).length), style));
                }
            }
            // Selection changes also enter Affinity's history. Include the
            // final frame selection in the same undo step as the corrections.
            if (originalSpread && !originalSpread.isSameNode(commandSpread))
                commands.addCommand(DocumentCommand.createSetCurrentSpread(originalSpread));
            commands.addCommand(DocumentCommand.createSetSelection(
                Selection.create(doc, Array.from(originalSelection.nodes))));
            doc.executeCommand(commands.createCommand());
            app.alert("Korjattu " + pending.length + " kohtaa. Voit kumota korjaukset yhdellä Undo-komennolla.",
                "Suomen oikoluku");
        } finally {
            clearHighlight();
            // Restore frame selection, not the old text offsets after edits.
            // Preview restores the original selection on Cancel; no history
            // entry or permanent highlight is created by simply reviewing.
        }
    }
    checkBatches();
}

if (typeof process !== "undefined" && process.versions && process.versions.node) {
    module.exports = VoikkoCore;
} else {
    try { runAffinityVoikko(); }
    catch (error) { require("/application.js").app.alert(String(error.message || error), "Suomen oikoluku"); }
}
